/**
 * What enrolls a Contact in an automation, by `kind`: an Event matcher or a date
 */
export type AutomationTrigger = ({
  kind: 'event';
} & EventTrigger) | ({
  kind: 'date';
} & DateTrigger);

/**
 * What enrolls a Contact in an automation, by `kind`: an Event matcher or a date
 */
export type AutomationTriggerInput = ({
  kind: 'event';
} & EventTriggerInput) | ({
  kind: 'date';
} & DateTriggerInput);

/**
 * One version of an automation's definition: what publishing makes it do (ADR 0065)
 */
export type AutomationVersion = {
  /**
   * 1 for the first version, plus one per version after it
   */
  number: number;
  /**
   * What enrolls a contact
   */
  trigger: AutomationTrigger;
  /**
   * The Event matchers that end an active enrollment early, as exited. Only an Event that
   * occurred once the enrollment began counts; machine opens and clicks never do.
   */
  exitEvents: Array<EventMatcher>;
  /**
   * The Event matcher that ends an active enrollment as goal_reached; an Event that matches it and
   * an exit reaches the goal. Null when there is none.
   */
  goalEvent: EventMatcher | null;
  /**
   * The version's Steps: its root path
   */
  steps: AutomationPath;
};

/**
 * The messages one version's send Step sent
 */
export type AutomationVersionStepFigures = {
  /**
   * The version's number
   */
  version: number;
  /**
   * The Step's id
   */
  stepId: StepId;
  /**
   * Messages the provider accepted
   */
  sent: number;
  /**
   * Messages skipped, as in AutomationStepFigures
   */
  skipped: number;
  /**
   * The skipped messages by Skipped reason, as in AutomationStepFigures
   */
  skippedByReason: Array<SkippedReasonCount>;
  /**
   * The active enrollments of the version standing on the Step whose send waits now, by cause, as
   * in AutomationStepFigures
   */
  waitingByCause: Array<DeferralCauseCount>;
  /**
   * Messages sent whose Sending window judged them by a single time zone, as in
   * AutomationStepFigures
   */
  singleZone: number;
};

/**
 * The enrollments that went on at once from one Wait until on a date instead of waiting, by why:
 * read from what each kept when it reached the Step, counted on the moment it left it
 */
export type AutomationWaitUntilFigures = {
  /**
   * The Wait until's Step id, the same in every version
   */
  stepId: StepId;
  /**
   * Its moment had passed: a once date before the arrival
   */
  past: number;
  /**
   * The contact held no date in the field, or a value that is no date
   */
  noDate: number;
  /**
   * Its moment lay more than 366 days ahead, such as a yearly date whose value is itself in the
   * future
   */
  beyondBound: number;
};

/**
 * A Wait for event waits for an Event one of its Event matchers matches, on the Contact its
 * Condition, if any, holds for (ADR 0124, ADR 0180)
 */
export type AwaitedEvent = {
  kind: 'event';
  /**
   * The Event matchers it waits for: an Event of a matcher's action whose properties pass its
   * filter
   */
  matchers: Array<EventMatcher>;
  /**
   * The tests the Contact and the Event the Enrollment began with must pass when the Event is
   * handled; absent, every matching Event arrives
   */
  condition?: WaitForEventCondition;
};

/**
 * A Wait for event waits for an Event one of its Event matchers matches, as a request writes it
 */
export type AwaitedEventInput = {
  kind: 'event';
  /**
   * The Event matchers it waits for, at least one, none twice: an Event of a matcher's action whose
   * properties pass its filter. A matcher on an action an exit or the goal of the version matches
   * with no filter refuses the save, naming the Step: that Event would end the enrollment, never
   * take `arrived`.
   */
  matchers: Array<EventMatcherInput>;
  /**
   * The tests the Contact and the Event the Enrollment began with must pass when the Event is
   * handled, read on the Contact's live data; false and unknown leave the Enrollment waiting.
   * Omitted, every matching Event arrives.
   */
  condition?: WaitForEventConditionInput;
};

