/**
 * Request body for the share of a broadcast's audience outside its Sending window: the audience, as the segment preview names it, and a moment
 */
export type SiteBroadcastOutsideWindowInput = {
  /**
   * The condition of the broadcast's segment; absent means all contacts
   */
  condition?: SegmentConditionInput;
  /**
   * The broadcast's Channel
   */
  channel: BroadcastChannel;
  /**
   * The Integration the broadcast routes through; null or absent is the Channel's default
   */
  integrationId?: EntityId | null;
  /**
   * The moment the broadcast would be scheduled at
   */
  scheduledAt: Timestamp;
};

/**
 * How many of a broadcast's recipients the Sending window would hold at a moment (ADR 0134)
 */
export type SiteBroadcastOutsideWindowResult = {
  /**
   * How many of the recipients the broadcast would take would wait for their Sending window to
   * open. A recipient whose zones are never open at once is skipped (no_local_time), not counted.
   * Always 0 on email and Telegram, which no window holds.
   */
  held: number;
  /**
   * When the last of them is reached: the latest moment their windows open. Absent when none is held.
   */
  reachedAt?: Timestamp;
};

/**
 * How far a sending broadcast has got. A broadcast limited by its Integration's Provider
 * limit is paced: recipients go out at an even interval. The Workspace's Send cap lets a
 * day's worth out at a time. The estimate is derived on the server from both, the later
 * of the two, and `limitedBy` says which one it is.
 */
export type SiteBroadcastProgress = {
  /**
   * Recipients already decided: sent, skipped or failed
   */
  processedCount: number;
  /**
   * Recipients still waiting to be sent
   */
  remainingCount: number;
  /**
   * When the last remaining recipient is expected to be sent. Null when it is not
   * knowable: the broadcast is on hold, or nothing limits it.
   */
  estimatedCompletionAt?: Timestamp | null;
  /**
   * What slows the broadcast and sets the estimate; null when nothing does or it is on hold
   */
  limitedBy: SiteBroadcastLimit | null;
};

/**
 * Broadcast resource used by the site UI
 */
export type SiteBroadcastResource = {
  /**
   * Unique identifier
   */
  id: EntityId;
  /**
   * Internal broadcast name
   */
  name: string;
  /**
   * The Channel the broadcast sends on, fixed when it was created
   */
  channel: BroadcastChannel;
  /**
   * What the broadcast says, in the shape of its Channel
   */
  content: BroadcastContent;
  /**
   * Warnings of the lint over the stored content (ADR 0040); set on the response of a save, never blocks it
   */
  warnings?: Array<LintFinding>;
  /**
   * Target segment; null means all contacts. Once the broadcast leaves draft it holds a copy of
   * the segment's condition taken then, and this names the segment only as where its audience
   * came from.
   */
  segmentId?: EntityId | null;
  /**
   * Sending integration; null means the workspace default
   */
  integrationId?: EntityId | null;
  /**
   * Lifecycle status
   */
  status: BroadcastStatus;
  /**
   * Why sending is currently held, when it is
   */
  holdReason?: HoldReason | null;
  /**
   * When the broadcast is scheduled to send
   */
  scheduledAt?: Timestamp | null;
  /**
   * The recipients the broadcast would take at the moment it was scheduled: its audience's contacts with a destination on its Channel that is neither suppressed nor unsubscribed (ADR 0149). Answered by Schedule only. It is the count at Schedule, not a promise: recipients are resolved at send time from the condition copied then (ADR 0065).
   */
  recipients?: number;
  /**
   * The recipients Cancel left unsent: those with no message when it landed (ADR 0150). A message already handed to the provider goes out and is not counted. Answered by Cancel only.
   */
  unsent?: number;
  /**
   * When the broadcast finished sending
   */
  sentAt?: Timestamp | null;
  /**
   * When the broadcast failed
   */
  failedAt?: Timestamp | null;
  /**
   * Delivery counters
   */
  stats: SiteBroadcastStats;
  /**
   * Progress and ETA while the broadcast is sending; null otherwise. Returned by get and send only, never by the list
   */
  progress?: SiteBroadcastProgress | null;
  /**
   * When the broadcast was archived; null while it is kept. An archived broadcast is read-only until it is unarchived.
   */
  archivedAt?: Timestamp | null;
  /**
   * The revision of the state this answer shows (ADR 0119): an update, Send now and Schedule name it
   */
  revision: Revision;
  /**
   * Creation timestamp
   */
  createdAt: Timestamp;
  /**
   * Last update timestamp
   */
  updatedAt: Timestamp;
};

/**
 * Delivery figures of a broadcast, derived from its recipients and their messages, per Channel
 * (ADR 0080): every Channel reports recipients, sent, skipped, failed, pending, clicked and
 * unsubscribed. A figure the broadcast's Channel does not report is null, never zero: Telegram
 * reports no delivered, opened, bounced or complained count and so no delivery or open rate; SMS
 * reports delivered and undelivered, and no opened, bounced or complained count, delivery or open
 * rate; only SMS reports undelivered.
 */
export type SiteBroadcastStats = {
  /**
   * Number of recipients the broadcast targets
   */
  recipientsTotal: number;
  /**
   * Messages successfully handed to the provider
   */
  sentCount: number;
  /**
   * Recipients skipped at send time: no destination any more, or an opt-out that landed after planning
   */
  skippedCount: number;
  /**
   * The skipped recipients by Skipped reason (ADR 0178): every reason of the closed list in its order, one none was skipped for at zero; they add up to `skippedCount`
   */
  skippedByReason: Array<SkippedReasonCount>;
  /**
   * The pending recipients whose send waits now, by the cause of its latest Deferral (ADR 0178): every cause of the closed list in its order, one none waits for at zero; all zero once the broadcast is no longer sending
   */
  waitingByCause: Array<DeferralCauseCount>;
  /**
   * Messages sent whose Sending window judged them by a single time zone (ADR 0134): the recipient could be in one zone only, so the window held exactly to its hours; null on a Channel with no Sending window
   */
  singleZoneCount: number | null;
  /**
   * Messages that failed to send
   */
  failedCount: number;
  /**
   * Recipients whose send has not ended yet; none on a cancelled broadcast but a message already handed over
   */
  pendingCount: number;
  /**
   * Recipients a Cancel left unsent: no message was created for them (ADR 0150). Zero unless the broadcast is cancelled.
   */
  cancelledCount: number;
  /**
   * Tracked messages that were opened; null on a Channel that cannot tell
   */
  openedCount: number | null;
  /**
   * Tracked messages that were clicked
   */
  clickedCount: number;
  /**
   * Messages sent that are not tracked: sent untracked, or whose tracking was withdrawn since (ADR 0120). They count in no open or click figure, and the tracked messages are the sent count less these.
   */
  untrackedCount: number;
  /**
   * Recipients that unsubscribed via this broadcast
   */
  unsubscribedCount: number;
  /**
   * Messages the provider reported delivered, read from the delivery result stamped on each message; null on a Channel whose provider reports none
   */
  deliveredCount: number | null;
  /**
   * Messages the provider reported undelivered (an SMS the carrier could not deliver), read from the delivery result stamped on each message; null on a Channel whose provider reports none
   */
  undeliveredCount: number | null;
  /**
   * Messages the provider reported bounced, read from the delivery result stamped on each message; null on a Channel whose provider reports none
   */
  bouncedCount: number | null;
  /**
   * Messages a recipient complained about, read from the delivery result stamped on each message; null on a Channel whose provider reports none
   */
  complainedCount: number | null;
  /**
   * Messages that went through a Test inbox: captured, not delivered; they count as delivered too. Null off email.
   */
  capturedCount: number | null;
  /**
   * Messages handed to the provider ÷ recipients targeted (0–1); null on a Channel that reports no delivery
   */
  deliveryRate: number | null;
  /**
   * Unique opens ÷ tracked messages sent (0–1); null on a Channel that reports no opens
   */
  openRate: number | null;
  /**
   * Unique clicks ÷ tracked messages sent (0–1)
   */
  clickRate: number;
  /**
   * Unique clicks ÷ unique opens (0–1); null on a Channel that reports no opens
   */
  clickToOpenRate: number | null;
  /**
   * Unsubscribes ÷ messages sent (0–1)
   */
  unsubscribeRate: number;
  /**
   * Send failures ÷ recipients targeted (0–1)
   */
  failureRate: number;
  /**
   * Orders credited to the Broadcast and their net revenue (ADR 0064)
   */
  revenue: MessageRevenue;
};

